        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from concurrent access to the `sysctl_tcp_migrate_req` variable, which can be modified while being read. This leads to data races, where the value read may not reflect the actual state due to simultaneous updates, potentially causing incorrect behavior in TCP migration handling.

        Commit message:
        tcp: Fix data-races around sysctl_tcp_migrate_req.

While reading sysctl_tcp_migrate_req, it can be changed concurrently.
Thus, we need to add READ_ONCE() to its readers.

Fixes: f9ac779f881c ("net: Introduce net.ipv4.tcp_migrate_req.")
Signed-off-by: Kuniyuki Iwashima <kuniyu@amazon.com>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:

 void reuseport_stop_listen_sock(struct sock *sk)
 {
 	if (sk->sk_protocol == IPPROTO_TCP) {
 		struct sock_reuseport *reuse;
 		struct bpf_prog *prog;

 		spin_lock_bh(&reuseport_lock);

 		reuse = rcu_dereference_protected(sk->sk_reuseport_cb,
 						  lockdep_is_held(&reuseport_lock));
 		prog = rcu_dereference_protected(reuse->prog,
 						 lockdep_is_held(&reuseport_lock));

-		if (sock_net(sk)->ipv4.sysctl_tcp_migrate_req ||
+		if (READ_ONCE(sock_net(sk)->ipv4.sysctl_tcp_migrate_req) ||
 		    (prog && prog->expected_attach_type == BPF_SK_REUSEPORT_SELECT_OR_MIGRATE)) {
 			/* Migration capable, move sk from the listening section
 			 * to the closed section.
 			 */
 			bpf_sk_reuseport_detach(sk);

 			__reuseport_detach_sock(sk, reuse);
 			__reuseport_add_closed_sock(sk, reuse);

 			spin_unlock_bh(&reuseport_lock);
 			return;
 		}

 		spin_unlock_bh(&reuseport_lock);
 	}

 	/* Not capable to do migration, detach immediately */
 	reuseport_detach_sock(sk);
 }
 EXPORT_SYMBOL(reuseport_stop_listen_sock);
  */
 struct sock *reuseport_migrate_sock(struct sock *sk,
 				    struct sock *migrating_sk,
 				    struct sk_buff *skb)
 {
 	struct sock_reuseport *reuse;
 	struct sock *nsk = NULL;
 	bool allocated = false;
 	struct bpf_prog *prog;
 	u16 socks;
 	u32 hash;

 	rcu_read_lock();

 	reuse = rcu_dereference(sk->sk_reuseport_cb);
 	if (!reuse)
 		goto out;

 	socks = READ_ONCE(reuse->num_socks);
 	if (unlikely(!socks))
 		goto failure;

 	/* paired with smp_wmb() in __reuseport_add_sock() */
 	smp_rmb();

 	hash = migrating_sk->sk_hash;
 	prog = rcu_dereference(reuse->prog);
 	if (!prog || prog->expected_attach_type != BPF_SK_REUSEPORT_SELECT_OR_MIGRATE) {
-		if (sock_net(sk)->ipv4.sysctl_tcp_migrate_req)
+		if (READ_ONCE(sock_net(sk)->ipv4.sysctl_tcp_migrate_req))
 			goto select_by_hash;
 		goto failure;
 	}

 	if (!skb) {
 		skb = alloc_skb(0, GFP_ATOMIC);
 		if (!skb)
 			goto failure;
 		allocated = true;
 	}

 	nsk = bpf_run_sk_reuseport(reuse, sk, prog, skb, migrating_sk, hash);

 	if (allocated)
 		kfree_skb(skb);

 select_by_hash:
 	if (!nsk)
 		nsk = reuseport_select_sock_by_hash(reuse, hash, socks);

 	if (IS_ERR_OR_NULL(nsk) || unlikely(!refcount_inc_not_zero(&nsk->sk_refcnt))) {
 		nsk = NULL;
 		goto failure;
 	}

 out:
 	rcu_read_unlock();
 	return nsk;

 failure:
 	__NET_INC_STATS(sock_net(sk), LINUX_MIB_TCPMIGRATEREQFAILURE);
 	goto out;
 }
 EXPORT_SYMBOL(reuseport_migrate_sock);


